import {mountGuide,closeTour} from './guide.js?v=20261018-hannah1';
const $=id=>document.getElementById(id),esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TZ='America/Los_Angeles',KEY='hic-second-peak-v1';
const dateFmt=new Intl.DateTimeFormat('en-CA',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'}),timeFmt=new Intl.DateTimeFormat('en-US',{timeZone:TZ,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true,timeZoneName:'short'});
const dayCache=new Map(),hourCache=new Map();
const weekdayFmt=new Intl.DateTimeFormat('en-US',{timeZone:TZ,weekday:'short'});
function displayDay(value,compact=false){const date=new Date(value+'T12:00:00Z');const weekday=new Intl.DateTimeFormat('en-US',{timeZone:'UTC',weekday:'short'}).format(date);return compact?`${weekday} ${value.slice(5)}`:new Intl.DateTimeFormat('en-US',{timeZone:'UTC',weekday:'short',month:'short',day:'numeric',year:'numeric'}).format(date)}
const dayOf=e=>{if(dayCache.has(e.timestamp))return dayCache.get(e.timestamp);const p=Object.fromEntries(dateFmt.formatToParts(new Date(e.timestamp)).map(x=>[x.type,x.value]));const v=`${p.year}-${p.month}-${p.day}`;dayCache.set(e.timestamp,v);return v},hourOf=e=>{if(hourCache.has(e.timestamp))return hourCache.get(e.timestamp);const h=+new Intl.DateTimeFormat('en-US',{timeZone:TZ,hour:'numeric',hourCycle:'h23'}).format(new Date(e.timestamp));hourCache.set(e.timestamp,h);return h},stamp=e=>`${weekdayFmt.format(new Date(e.timestamp))}, ${dayOf(e)} ${timeFmt.format(new Date(e.timestamp))}`;
const phases=['Understand the asset','Establish the baseline / SIEM','Identify the deviation','Investigate authentication','Consider MITRE ATT&CK','Investigate data movement','Prepare escalation brief'];
const questions=['Asset and business significance','Expected operating conditions','Observed deviations','Supporting evidence: event IDs and timestamps','Potential MITRE ATT&CK classification and rationale','Status of authentication safeguards','Network traffic and possible exfiltration findings','Known, unknown, and not established','Recommended next steps and responsible parties'];
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
const state={phase:0,pins:[],notes:Array(9).fill(''),...saved};state.phase=Number.isInteger(state.phase)&&state.phase>=0&&state.phase<7?state.phase:0;state.pins=Array.isArray(state.pins)?state.pins:[];state.notes=Array.isArray(state.notes)&&state.notes.length===9?state.notes.map(String):Array(9).fill('');
let ledger,events=[],days=[],filter={date:'all',category:'all',from:'00:00',to:'24:00',user:'',ip:'',outcome:'all',q:''},mode='daily',sort={key:'timestamp',asc:true},page=0,selectedBin=null;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saveStatus').textContent='Saved on this browser'}catch{$('saveStatus').textContent='Storage unavailable · export before leaving'}}
function setPhase(n){state.phase=n;persist();page=0;selectedBin=null;if(n===1){filter.date='all';mode='daily'}if(n===2||n===3||n===5){filter.date='2026-08-15';mode='hourly'}filter.from='00:00';filter.to='24:00';filter.category=n===3?'authentication':'all';if(n===5){filter.from='05:12';filter.to='17:21'};filter.user='';filter.ip='';filter.outcome='all';filter.q='';render();$('main').focus({preventScroll:true});window.scrollTo({top:0,left:0,behavior:'instant'})}
function heading(eye,title,copy){return `<div class="eyebrow">${eye}</div><h2>${title}</h2><p class="intro">${copy}</p>`}
function hint(items){return `<details class="hint"><summary>Need a starting point? Optional hints</summary>${items.map((v,i)=>`<details><summary>Hint ${i+1}</summary><p>${v}</p></details>`).join('')}</details>`}
function nav(){return `<div class="next-row no-print"><button id="previous" ${state.phase===0?'disabled':''}>← Previous phase</button><button class="primary" id="next" ${state.phase===6?'disabled':''}>Continue: ${phases[state.phase+1]||'Complete'} →</button></div>`}

const flowSteps=[
 {node:0,title:'Prepare the payment batch',copy:'Accounts Payable in Cincinnati assembles 47 supplier-payment instructions totaling $2.8 million for international partners. Preparation is not permission to transmit.',log:'Business context: proposed payment batch prepared.'},
 {node:1,title:'Approve the instructions',copy:'U.S. Treasury reviews and approves the payees and amounts. The London operator can submit this approved batch but cannot independently change its amounts or add beneficiaries.',log:'Business context: approved batch ready for submission.'},
 {node:2,title:'Begin the scheduled operator sign-in',copy:'A designated London operator connects through the approved corporate network or VPN during 9 PM–midnight Pacific Time. This is a scheduled 5–8 AM London shift the next day in this August case.',log:'Identity records: account, source network, time and password result.'},
 {node:3,title:'Verify both factors and open a session',copy:'The identity service verifies the individual password and MFA. Only after both required checks succeed should the gateway issue an application session. Password success alone is not a completed login.',log:'Identity + application records: MFA result and session creation.'},
 {node:3,title:'Submit the approved batch',copy:'The signed-in operator asks the Batch Transfer Gateway to submit the already-approved instructions. The gateway records the operator, session and batch identifiers.',log:'Gateway records: approved batch submitted within the authorized session.'},
 {node:4,title:'Transmit to the approved bank',copy:'The gateway sends the payment instruction file to the banking partner over SFTP, an encrypted file-transfer connection. Network records show the destination and the amount of data sent and received.',log:'Network records: approved bank destination, SFTP and byte counters.'},
 {node:4,title:'Receive acknowledgement; end the session',copy:'The bank acknowledges receipt, and the operator signs out. This completes the expected single daily processing session. Acknowledgement means receipt of instructions, not proof of final payment settlement.',log:'Gateway records: bank acknowledgement and operator sign-out.'}
];
let flowTimer=null,flowIndex=0;
function expectedFlow(){return `<section class="expected-flow" aria-labelledby="flowTitle"><div class="panel-top"><div><span class="eyebrow">ANIMATED WALKTHROUGH / EXPECTED OPERATION</span><h3 id="flowTitle">How one authorized payment session should work</h3></div><span class="badge">Expected process · not incident evidence</span></div><p class="section-note">Follow the people, checks and connections. Then use their records in the SIEM to investigate the unexpected activity.</p><div class="flow-nodes" role="group" aria-label="Payment process components">${[['AP','Accounts Payable','Cincinnati · prepares instructions'],['✓','U.S. Treasury','Approves payees and amounts'],['OP','London operator','Scheduled shift · corporate network / VPN'],['GW','Batch Transfer Gateway','Identity service + MFA → session'],['BK','Banking partner','Receives payment instructions']].map(([icon,name,desc],i)=>`<div class="flow-node" data-flow-node="${i}"><span class="component-icon" aria-hidden="true">${icon}</span><strong>${name}</strong><small>${desc}</small></div>`).join('')}</div><div class="flow-track" aria-hidden="true"><span id="flowPacket"></span></div><div class="flow-controls"><button class="primary" id="flowPlay">Play walkthrough</button><button id="flowNext">Next step →</button><button id="flowRestart">Restart</button><span id="flowCounter">Step 1 of 7</span></div><div class="flow-narration" aria-live="polite" aria-atomic="true"><h4 id="flowStepTitle"></h4><p id="flowStepCopy"></p></div><div class="siem-collector"><div class="siem-icon" aria-hidden="true">▥</div><div><strong>SIEM · your investigation console</strong><p>The tool collects identity, gateway and network records so you can compare what happened with the expected process. It observes these systems; it does not approve or send payments.</p><div id="flowLog" class="flow-log"></div></div></div><p class="caption">For this case, normal operation has one authorized sign-in/session and one approved batch each day. Many log events can belong to that one session. The apparent second sign-in period needs investigation; an activity peak alone does not establish a successful login or another payment.</p></section>`}
function bindFlow(){flowIndex=0;const paint=()=>{const step=flowSteps[flowIndex];document.querySelectorAll('[data-flow-node]').forEach(n=>{const index=+n.dataset.flowNode;n.classList.toggle('current',index===step.node);n.classList.toggle('passed',index<step.node)});$('flowPacket').style.left=`${step.node*25}%`;$('flowCounter').textContent=`Step ${flowIndex+1} of ${flowSteps.length}`;$('flowStepTitle').textContent=step.title;$('flowStepCopy').textContent=step.copy;$('flowLog').textContent=step.log;$('flowNext').disabled=flowIndex===flowSteps.length-1;if(!flowTimer){$('flowPlay').textContent=flowIndex===flowSteps.length-1?'Replay walkthrough':'Play walkthrough';$('flowPlay').setAttribute('aria-pressed','false')};};const stop=()=>{clearInterval(flowTimer);flowTimer=null;$('flowPlay').textContent=flowIndex===flowSteps.length-1?'Replay walkthrough':'Play walkthrough';$('flowPlay').setAttribute('aria-pressed','false')};$('flowPlay').onclick=()=>{if(flowTimer){stop();return}if(flowIndex===flowSteps.length-1)flowIndex=0;paint();$('flowPlay').textContent='Pause walkthrough';$('flowPlay').setAttribute('aria-pressed','true');flowTimer=setInterval(()=>{if(!document.getElementById('flowTitle')){clearInterval(flowTimer);flowTimer=null;return}flowIndex++;paint();if(flowIndex===flowSteps.length-1)stop()},6500)};$('flowNext').onclick=()=>{stop();flowIndex=Math.min(flowSteps.length-1,flowIndex+1);paint()};$('flowRestart').onclick=()=>{stop();flowIndex=0;paint()};paint();}

function ticket(){return heading('EXERCISE / START HERE','Your investigation, at a glance.','Investigate an unexpected sign-in period in a manufacturer’s international payment system, then report what the evidence supports.')+`<section class="panel quick-brief"><div class="brief-point"><span>01</span><div><h3>What should happen</h3><p>Hamilton Industrial Components (HIC) pays international suppliers for goods and work. Its finance team prepares and approves a batch of payments. A London operator should sign in once between <strong>9 PM and midnight Pacific Time</strong>, pass password and MFA checks, and use the <strong>Batch Transfer Gateway</strong> to send the approved file to the bank.</p></div></div><div class="brief-point"><span>02</span><div><h3>What we think may have happened</h3><p>The business team reports sending just one approved batch, but one day appears to have <strong>two sign-in periods</strong>, including activity at an unexpected time. Someone may have tried to access the gateway without authorization. The report alone does not establish a successful login or another payment.</p></div></div><div class="brief-point"><span>03</span><div><h3>Your mission</h3><p>Use the <strong>simulated SIEM</strong>—a tool that brings security records together—to find that day, inspect the unexpected sign-in activity, and check for <strong>unusual large data transfers</strong> during and afterward. Pin supporting records and prepare a short escalation brief explaining what you know, what remains uncertain, and who should act next.</p></div></div><div class="start-investigation"><button class="primary" id="startInvestigation">Open the SIEM: establish the baseline →</button><span>This opens phase 2, “Establish the baseline / SIEM”—the same destination as the sidebar link.</span></div><p class="caption">Fictional case · 60–90 minutes · no installation. Notes stay in this browser. Use event IDs to inspect and pin evidence; export your brief in phase 7.</p></section><details class="panel optional-reference"><summary>Optional: watch how the authorized process works</summary>${expectedFlow()}</details><details class="panel optional-reference"><summary>Reference: asset, people and approved connections</summary><p class="section-note">Accounts Payable prepares supplier payments. U.S. Treasury manages the company’s money and approves the batch. London Treasury Operations submits it. The approved batch contains 47 payment instructions totaling $2.8 million.</p>${assetProfile()}</details>`}
function assetProfile(){return `<section class="panel"><h3>Asset profile / BTG-01</h3><dl class="facts"><dt>Purpose</dt><dd>Batch Transfer Gateway · <code>192.0.2.40</code><br>Transmits approved supplier-payment instructions.</dd><dt>Business owner</dt><dd>U.S. Treasury; operated by London Treasury Operations.</dd><dt>Operators</dt><dd>Asha Patel (<code>a.patel</code>), Emma Clarke (<code>e.clarke</code>), Max Weber (<code>m.weber</code>).</dd><dt>Access window</dt><dd>9 PM–midnight Pacific Time. Designated London staff work a scheduled early-morning settlement shift (5–8 AM BST the next day in this August case), with a documented handover.</dd><dt>Approved origins</dt><dd><code>198.51.100.24</code> London corporate egress; <code>198.51.100.25</code> corporate VPN egress.</dd><dt>Authentication</dt><dd>Individual credentials + MFA. A verified password alone must not issue a session.</dd><dt>Permissions</dt><dd>Submit approved batches; cannot create beneficiaries or change approved payment amounts.</dd><dt>Approved bank</dt><dd><code>203.0.113.80</code> · SFTP payment channel.</dd><dt>Other services</dt><dd><code>192.0.2.53</code> DNS resolver; <code>198.51.100.90</code> corporate monitoring collector (HTTPS).</dd></dl></section>`}
function minutes(v){const [h,m]=v.split(':').map(Number);return h*60+m}
function baseMatches(e,ignoreTime=false){const m=hourOf(e)*60+Number(e.timestamp.slice(14,16));return (filter.date==='all'||dayOf(e)===filter.date)&&(filter.category==='all'||e.category===filter.category)&&(!filter.user||String(e.user||'').toLowerCase().includes(filter.user.toLowerCase()))&&(!filter.ip||e.src.includes(filter.ip)||e.dst.includes(filter.ip))&&(filter.outcome==='all'||e.outcome===filter.outcome)&&(!filter.q||JSON.stringify(e).toLowerCase().includes(filter.q.toLowerCase()))&&(ignoreTime||(m>=minutes(filter.from)&&m<minutes(filter.to)))}
function visibleEvents(){return events.filter(e=>baseMatches(e))}
function clockLabel(value,compact=false){const [h,m]=value.split(':').map(Number);if(h===24)return 'Midnight (end of day)';const suffix=h<12?'AM':'PM';return `${h%12||12}${compact&&m===0?'':':'+String(m).padStart(2,'0')} ${suffix}`}
function timeChoices(selected,end=false){return [...new Set(Array.from({length:end?97:96},(_,i)=>`${String(Math.floor(i/4)).padStart(2,'0')}:${String(i%4*15).padStart(2,'0')}`).concat(['05:12','05:21','17:21',selected]))].filter(v=>end||v!=='24:00').sort().map(v=>`<option value="${v}" ${selected===v?'selected':''}>${clockLabel(v)}</option>`).join('')}
function controls(network=false){return `<div class="toolbar no-print"><label>Date<select id="date"><option value="all">All six days</option>${days.map(d=>`<option value="${d}" ${filter.date===d?'selected':''}>${displayDay(d)}</option>`).join('')}</select></label><label>From (PT)<select id="from">${timeChoices(filter.from)}</select></label><label>Until (exclusive)<select id="to">${timeChoices(filter.to,true)}</select></label><label>Account contains<input id="user" value="${esc(filter.user)}" placeholder="e.g. a.patel"></label><label>Source or destination IP<input id="ip" value="${esc(filter.ip)}" placeholder="e.g. 203.0.113."></label><label>Overall outcome<select id="outcome">${['all','success','failure','blocked'].map(x=>`<option ${filter.outcome===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="search">Search any field<input id="search" value="${esc(filter.q)}" placeholder="Event ID, batch, session, description…"></label><button id="clearFilters">Clear filters</button></div>${network?'':`<div id="activityFilters" class="chips no-print">${[['all','All activity'],['authentication','Authentication'],['application','HTTPS / application'],['transfer','SFTP / file transfers'],['network','Network connections'],['background','Other / background']].map(([k,v])=>`<button data-category="${k}" class="${filter.category===k?'active':''}">${v}</button>`).join('')}</div>`}`}
function evidenceGuide(){const authentication=state.phase===3;const records=authentication?[
 ['HIC-02365','First early-morning failure: outside the approved window, unexpected source, no session.'],
 ['HIC-02367','A second failure three seconds later: pin with the first record to demonstrate repetition.'],
 ['HIC-02639','Important exception: password verified, but MFA failed. Overall authentication failed; no session was issued.'],
 ['HIC-02283','Evening comparison: password and MFA succeed at the expected time from the approved VPN.'],
 ['HIC-02284','The next event establishes the legitimate session. Compare this with the absence of a morning session.']
 ]:[['HIC-02365','Anchor the unexpected activity: Saturday morning, outside the permitted window.'],['HIC-02283','Anchor the expected activity: Saturday evening, inside the permitted window.'],['HIC-02361','The approved evening batch submission: activity counts are not payment counts.']];return `<section class="panel evidence-guidance"><span class="eyebrow">HARISSA’S EVIDENCE CHECKPOINT</span><h3>${authentication?'Compare failed attempts with a completed sign-in':'Two activity periods, different outcomes'}</h3><div class="grid"><div class="callout"><strong>Unexpected · Saturday, Aug 15 · 5:12–5:20:57 AM PT</strong><p>All 180 sign-in attempts have an <strong>overall failure</strong>. Most fail the password check. One passes the password check but fails MFA. None creates an application session.</p></div><div class="callout"><strong>Expected · Saturday, Aug 15 · 9:07 PM PT</strong><p>The authorized operator passes <strong>both password and MFA</strong>, then opens a session at 9:07:01 PM. The approved batch is submitted at 9:35 PM, inside the 9 PM–midnight window.</p></div></div><p><strong>What this tells you:</strong> the extra morning peak represents failed access attempts, not a second confirmed successful login. Contrast the timing, origin and safeguard outcomes with the authorized evening session.</p><div class="toolbar"><button data-evidence-window="morning">Show morning authentication failures</button><button data-evidence-window="evening">Show authorized evening activity</button></div><h4>Inspect and pin these specific records</h4><p class="caption">Use Inspect or Pin record below; you do not need to find these IDs manually in the table. Pinning saves a copy reference to that record in phase 7, alongside your notes. Pinned records appear in your printed report and JSON/CSV exports. Pinning does not by itself explain what the evidence means.</p><div class="evidence-list">${records.map(([id,why])=>{const e=events.find(e=>e.id===id);return `<div class="evidence-item"><div><strong>${id}</strong> · ${stamp(e)}<br>${why}</div><div class="recommended-actions"><button data-recommend-inspect="${id}">Inspect</button><button data-recommend-pin="${id}">${state.pins.includes(id)?'Pinned ✓':'Pin record'}</button></div></div>`}).join('')}</div></section>`}
function bindEvidenceGuide(){document.querySelectorAll('[data-recommend-inspect]').forEach(b=>b.onclick=()=>inspect(b.dataset.recommendInspect));document.querySelectorAll('[data-recommend-pin]').forEach(b=>b.onclick=()=>{const id=b.dataset.recommendPin;if(!state.pins.includes(id))state.pins.push(id);persist();b.textContent='Pinned ✓'});document.querySelectorAll('[data-evidence-window]').forEach(b=>b.onclick=()=>{const morning=b.dataset.evidenceWindow==='morning';guideView({date:'2026-08-15',mode:'hourly',hour:morning?5:21});filter.category=morning?'authentication':'all';document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x.dataset.category===filter.category));updateExplorer();$('chartArea').scrollIntoView({block:'start',behavior:'smooth'})})}
function networkGuide(){return `<section class="panel network-guide"><span class="eyebrow">HARISSA’S TRAFFIC CHECKPOINT</span><h3>Did the failed sign-ins lead to observed data extraction?</h3><div class="callout"><strong>Case finding: no exfiltration is identified in the supplied evidence.</strong><p>The morning sign-ins all fail overall, no unauthorized application session is recorded, and the following 12 hours show no unusual large outbound transfer. In this simulated case, the failed attempts do not lead to a recorded unauthorized session or data extraction.</p></div><h4>Read this view in three steps</h4><ol><li><strong>Use the investigation window already selected:</strong> Saturday, August 15, 5:12 AM–5:21 PM PT. It includes the attempts and at least 12 hours after they end. The shortcut below restores this window if you change it.</li><li><strong>Focus on orange outbound bars.</strong> Exfiltration means unauthorized data leaving the system. Purple inbound bars show data arriving; they are not evidence of data leaving. In this window, outbound totals 397,068 bytes—about 397 kB, not a large payment-data dump.</li><li><strong>Explain the extra bytes and inspect the records.</strong> The 397,068 outbound bytes comprise 240,728 bytes of normal DNS/monitoring traffic and 156,340 bytes of small HTTPS authentication exchanges. The latter are associated with the failed sign-in attempts; they do not establish an authenticated file transfer.</li></ol><div class="grid"><div class="callout"><strong>Unapproved destination: blocked</strong><p>Inspect <button class="link-button" data-network-inspect="HIC-02725">HIC-02725</button>: the 5:33 AM connection toward 203.0.113.210 was denied with zero recorded bytes sent. This is a follow-up lead, not an observed completed transfer.</p></div><div class="callout"><strong>Approved payment file: later that evening</strong><p>Inspect <button class="link-button" data-network-inspect="HIC-02362">HIC-02362</button>: the 9:35:02 PM SFTP transfer sends 243,000 bytes to the approved bank, linked to the authorized session and batch. It is outside the morning-to-afternoon window above.</p></div></div><p><strong>Report it precisely:</strong> “No successful unauthorized session or exfiltration is established in the supplied monitoring coverage; no unusual large outbound transfer was observed.” These logs do not show encrypted payload content or other systems, so this is not proof that extraction was impossible.</p></section>`}
function workspace(network=false){const n=state.phase;let title=n===1?'What does ordinary look like?':n===2?'Find the deviation.':n===3?'Reconstruct the authentication activity.':'Follow the data movement.';let copy=n===1?'Compare the days first. The Date menu filters to a day; it does not open its hourly timeline. To look within that day, click Hourly detail or click the day’s bar. The chart and event console use the same filters.':n===2?'Compare August 15 with the prior days. A peak counts events, not payments. Select an hour to investigate its records.':n===3?'Compare sources, accounts, timing, password checks, MFA outcomes, and session identifiers. Contrast the records with an authorized processing window.':'Review gateway-edge bytes during and after the unusual activity. Compare the same hours on historical days, inspect destinations, and distinguish transfer volume from proof of exfiltration.';
return heading(`PHASE 0${n+1} / EVIDENCE EXPLORER`,title,copy)+`${n===2||n===3?evidenceGuide():network?networkGuide():''}<section class="panel"><div class="panel-top"><div><h3>${network?'Gateway network volume':'Activity timeline'}</h3><span class="section-note">${network?'Bytes aggregated from edge-flow records only':'All counts derive from the event ledger'} · Pacific Time</span></div><div class="chips no-print"><button id="daily" class="${mode==='daily'?'active':''}">Daily overview</button><button id="hourly" class="${mode==='hourly'?'active':''}">Hourly detail</button></div></div>${controls(network)}${network?`<div class="toolbar no-print"><button id="postWindow">Review Sat, Aug 15 · 5:12 AM–5:21 PM PT</button><button id="approvedBank">Approved banking destination</button><button id="allDestinations">All destinations</button></div><p class="caption">Coverage ends August 16 at midnight PDT; includes more than 12 hours after the 5:12–5:20:57 AM sequence. A denied connection can identify an unusual destination without recording any bytes sent.</p>`:''}<div id="chartArea"></div></section><section class="panel"><div class="panel-top"><h3>Event log console</h3><span class="badge" id="logCount"></span></div><p class="caption">Open an event ID to inspect or pin it. Password and MFA are separate from overall outcome. All filters above also apply here. Sorting applies before pagination.</p><div id="logs"></div></section>${network?`<div class="callout"><strong>Be precise about what these records can establish.</strong><p>“No observed unusual large transfer,” “no confirmed exfiltration,” and “proof that no exfiltration occurred” are different claims. Volume records do not show payload content. This dataset has no endpoint forensics, other-host visibility, or bank settlement records.</p></div>`:''}${hint(n===1?['Inspect a prior date in hourly detail.','Compare the number of batch submissions with the total number of activity events.']:n===2?['Compare activity inside and outside 9 PM–midnight PT.','Filter by category and inspect the additional peak’s records.']:n===3?['Compare the origin against the asset profile.','Sort authentication records by time; inspect the spacing and account pattern.','Search for password verification success and inspect MFA and session fields.']:['Inspect both the authentication period and the following 12 hours.','Compare matching historical hours; review the approved destination list.','A zero-byte denied connection and a small exchange have different meanings. Check coverage limits.'])}`}
function attack(){return heading('PHASE 05 / REFERENCE DESK','From observation to technique.','Use ATT&CK as a vocabulary for a defensible interpretation. Naming a technique does not establish a compromise.')+`<section class="panel"><span class="badge">MITRE ATT&CK · Enterprise</span><h3 style="margin-top:15px">T1110 — Brute Force</h3><p>ATT&CK describes adversary behavior. A <strong>tactic</strong> is an objective (the “why”); a <strong>technique</strong> is a way of pursuing that objective (the “how”). T1110 belongs to the <strong>Credential Access</strong> tactic and describes repetitive attempts to obtain account access when credentials are unknown, including guessing passwords.</p><div class="flow-diagram" aria-label="Illustrative repeated authentication pattern, not case evidence"><div class="flow-step">Account + candidate password</div><span>→</span><div class="flow-step">Verification fails</div><span>→</span><div class="flow-step">Repeat / next candidate</div><span>→</span><div class="flow-step">Compare timing and outcomes</div></div><p class="caption">Illustration only. Logs usually do not expose the actual candidate passwords. Repetition alone requires context.</p><p><a href="https://attack.mitre.org/techniques/T1110/" target="_blank" rel="noopener">Read the official MITRE T1110 reference ↗</a></p><section class="attack-bridge"><h3>How does this connect to your investigation?</h3><p>Think of ATT&amp;CK as a shared catalog of suspicious behaviors. It gives you a name for the pattern you have observed so another analyst can understand your assessment.</p><ol><li><strong>Start with your observations.</strong> HIC-02365 and HIC-02367 record failed sign-ins three seconds apart, before the authorized window, from the same unexpected origin. The wider morning sequence repeats across valid operator accounts.</li><li><strong>Explain the possible behavior.</strong> Repeated, regularly spaced attempts are consistent with someone using automation to try passwords. This is an inference from the pattern; the logs do not show the actual candidate passwords or software.</li><li><strong>Connect the behavior to the catalog.</strong> <strong>T1110 — Brute Force</strong> describes repetitive attempts to obtain account access. <strong>Credential Access</strong> is its tactic: the objective is obtaining usable account credentials. The technique is the way that objective may be pursued.</li><li><strong>Keep the outcome separate.</strong> HIC-02639 has password success but MFA failure and no session. HIC-02283 and HIC-02284 show what an authorized successful sign-in and session look like at 9:07 PM. A possible T1110 mapping does not mean the attempt succeeded.</li></ol><div class="callout"><strong>Example wording for your brief</strong><p>“The repeated, regularly spaced morning authentication failures are consistent with attempted password guessing, potentially MITRE ATT&amp;CK T1110 (Brute Force). The supplied records do not establish a successful unauthorized application session.”</p><p class="caption">Support that interpretation with your pinned records. The exact guessing method and the person responsible remain unestablished.</p></div></section><div class="grid"><div class="callout"><h4>Observation</h4><p>Describe timestamps, account names, origin, and results using event IDs. An event records something observed.</p></div><div class="callout"><h4>Inference</h4><p>Evaluate whether repetition, timing and context are consistent with automated password guessing. State what alternative explanations need checking.</p></div></div><p>Sub-techniques include password guessing, password cracking, password spraying, and credential stuffing. Without visibility of candidate passwords or tools, avoid claiming a specific method with certainty. Evaluate whether the case supports T1110; you can disagree if your evidence and reasoning support it.</p><p class="section-note">The unexpected source has simulated enrichment naming Turkmenistan, a Central Asian republic. This is exercise context, not proof of a person’s physical location. All addresses are documentation addresses.</p></section>${hint(['Return to authentication records and compare attempt spacing.','What result would establish an application session? Does a password result establish that by itself?'])}`}
function pinnedHtml(){return state.pins.map(id=>{const e=events.find(x=>x.id===id);return e?`<div class="evidence-item"><div><strong>${e.id}</strong> · ${stamp(e)}<br>${esc(e.type)} · ${esc(e.src)} → ${esc(e.dst)} · ${esc(e.user)}<br>${esc(e.description)}<br>Password: ${esc(e.password)} · MFA: ${esc(e.mfa)} · session: ${esc(e.session)} · out/in: ${e.bytes_out}/${e.bytes_in} B</div><button data-unpin="${id}" class="no-print">Remove</button></div>`:''}).join('')||'<p class="section-note">No evidence pinned yet. Open event IDs in the log console to add evidence.</p>'}
function caseDebrief(){return `<section class="case-debrief no-print" aria-labelledby="debriefTitle"><div class="debrief-heading"><span class="eyebrow">HARISSA’S CASE DEBRIEF / BEFORE YOU WRITE</span><h3 id="debriefTitle">Let’s review what happened—and what your report must explain.</h3><p>I’m speaking here as your independent adviser. Use this review to organize your evidence, then write your own assessment below.</p></div><article class="mentor-pane" id="reviewSequence"><img src="assets/harissa-investigative.png" alt="Hannah, thoughtfully reviewing the investigation"><div><h4>First, reconstruct the sequence.</h4><p>We began with a business question: why did one day appear to have two sign-in periods? Monday through Friday provided a normal comparison. Saturday had extra activity outside the authorized 9 PM–midnight window.</p><ol><li><strong>5:12–5:20:57 AM:</strong> 180 sign-in attempts from an unexpected origin all failed overall. <button class="link-button" data-debrief-inspect="HIC-02365">HIC-02365</button> and <button class="link-button" data-debrief-inspect="HIC-02367">HIC-02367</button> show failures three seconds apart. <button class="link-button" data-debrief-inspect="HIC-02639">HIC-02639</button> verifies a password but fails MFA and issues no session. That password result still warrants investigation.</li><li><strong>During and after the attempts:</strong> small network exchanges include responses to rejected sign-ins. The separate 5:33 AM connection in <button class="link-button" data-debrief-inspect="HIC-02725">HIC-02725</button> was blocked with zero bytes transferred. No unusual large outbound transfer or exfiltration is established in the supplied coverage.</li><li><strong>9:07 PM onward:</strong> <button class="link-button" data-debrief-inspect="HIC-02283">HIC-02283</button> passes password and MFA; <button class="link-button" data-debrief-inspect="HIC-02284">HIC-02284</button> opens the legitimate session. The approved batch is then submitted and sent to the bank during the expected window.</li></ol><p>The repeated morning pattern is consistent with attempted password guessing, potentially <strong>MITRE ATT&amp;CK T1110 — Brute Force</strong>. That classification describes possible behavior; it does not establish a successful compromise.</p></div></article><article class="mentor-pane" id="reviewCIA"><img src="assets/harissa-advisory.png" alt="Hannah, advising on business impact and the report"><div><h4>Then assess confidentiality, integrity and availability.</h4><p><strong>Confidentiality:</strong> the records do not establish unauthorized access to payment data or exfiltration. The verified password raises a credential-exposure concern that needs follow-up.</p><p><strong>Integrity:</strong> no unauthorized change to payment instructions is shown. The approved evening batch chain is recorded, but receipt does not prove final bank settlement.</p><p><strong>Availability:</strong> the supplied health and transaction records show no service outage; authorized processing continues. This is a finding within the provided coverage, not a complete resilience assessment.</p><div class="callout" id="reviewStakeholders"><strong>Why the wording matters</strong><p>Senior management, incident responders, Treasury and other stakeholders need a clear answer about whether the event led to data extraction or other harm. They use your report to decide what to preserve, investigate, contain and communicate. Say what the evidence establishes, what it does not establish, and what must be checked next. Neither an unsupported claim of a breach nor an unsupported guarantee of safety helps them.</p></div></div></article><article class="mentor-pane" id="reviewAssumptions"><img src="assets/harissa-advisory.png" alt="Hannah, explaining the exercise’s assumptions"><div><h4>What resembles real work—and what we simplified.</h4><p><strong>The realistic reasoning:</strong> start with the business asset and its authorized use, compare activity, correlate identity/application/network records, assess safeguards and possible impact, preserve evidence, and escalate to responsible people.</p><p><strong>Our teaching assumptions:</strong> the asset profile and approved addresses are supplied and treated as correct; timestamps and identifiers are already aligned; the provided records are internally consistent; baseline daily totals repeat exactly; and the important records are suggested to you. All people, payments, addresses and events are synthetic. Turkmenistan is simulated enrichment, not verified attribution.</p><p><strong>In a real investigation:</strong> ordinary totals vary; logs may be delayed, missing or inconsistent; clocks and identities need validation; and source geography can reflect a proxy or VPN. You would verify expectations with system and business owners, obtain evidence from authorized sources, preserve its provenance, and consider alternative explanations.</p><p><strong>Coverage limits:</strong> we have gateway, identity, health and edge-flow records for six days. We do not have encrypted payload contents, full endpoint forensics, other systems, later activity or bank settlement records. No observed exfiltration in this exercise’s coverage is not proof that extraction was impossible through every channel.</p></div></article><div class="debrief-purpose" id="reviewPurpose"><h4>What you have been practicing</h4><p>The purpose was to learn to <strong>use a security tool to discern activity, investigate a deviation, capture evidence and key observations, relate the pattern to a known attack method using MITRE ATT&amp;CK, assess possible effects on confidentiality, integrity and availability, and communicate the result clearly</strong>. Your brief is a handoff for downstream investigation or other authorized action—not merely a way to name an attack.</p><p>Now turn that process into your report. Cite the pinned records, distinguish observations from interpretation, state the limits, and recommend who should do what next.</p></div></section>`}
function brief(){return heading('PHASE 07 / ANALYST DELIVERABLE','Security Observation & Escalation Brief','Review Hannah’s debrief, then prepare a traceable account of the event for the next responsible people.')+caseDebrief()+`<section class="panel"><div class="callout no-print"><strong>Your work remains on this browser.</strong><p>Use Print / Save as PDF for a readable report, or export your notes and evidence. Exports are generated on this device. No student information is required.</p></div><p class="print-only">Ticket SEC-2026-0816 · Batch Transfer Gateway BTG-01 · Fictional training exercise · Times: Pacific Time</p>${questions.map((q,i)=>`<label class="note-label" for="note${i}">${i+1}. ${q}</label><textarea id="note${i}" data-note="${i}" placeholder="Record observations, cite evidence, and state limits…">${esc(state.notes[i])}</textarea><div class="print-only"><h3>${i+1}. ${q}</h3><div class="printed-answer" id="printed${i}">${esc(state.notes[i]||'Not completed.')}</div></div>`).join('')}<h3 style="margin-top:25px">Selected evidence / ${state.pins.length} records</h3><div class="evidence-list">${pinnedHtml()}</div><div class="toolbar export-actions"><button class="primary" id="printBrief">Print / Save as PDF</button><button id="exportJson">Download notes + evidence JSON</button><button id="exportCsv">Download notes + evidence CSV</button><button id="reviewBrief">Check reasoning</button></div><div id="feedback" class="callout feedback no-print" role="status"></div><p class="section-note no-print">The reasoning check is a transparent checklist, not a grade. It checks completeness, recognizable event citations, and phrases that may need qualification. It cannot judge whether your full analysis is correct.</p></section>`}
function render(){ closeTour(false);clearInterval(flowTimer);flowTimer=null; $('phases').innerHTML=phases.map((p,i)=>`<button class="phase ${state.phase===i?'active':''}" data-phase="${i}" aria-label="Phase ${i+1}: ${p}" ${state.phase===i?'aria-current="step"':''}><span>${i+1}</span><div class="phase-name">${p}</div></button>`).join('');$('main').innerHTML=(state.phase===0?ticket():state.phase===4?attack():state.phase===6?brief():workspace(state.phase===5))+nav();document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>setPhase(+b.dataset.phase));$('previous').onclick=()=>setPhase(state.phase-1);$('next').onclick=()=>setPhase(state.phase+1);if([1,2,3,5].includes(state.phase)){bindExplorer();updateExplorer();bindEvidenceGuide();document.querySelectorAll('[data-network-inspect]').forEach(b=>b.onclick=()=>inspect(b.dataset.networkInspect))}if(state.phase===6)bindBrief();if(state.phase===0){bindFlow();$('startInvestigation').onclick=()=>setPhase(1)}if(state.phase===0){const introduction=document.createElement('section');introduction.className='case-introduction';introduction.setAttribute('aria-labelledby','caseIntroTitle');introduction.innerHTML=`<span class="eyebrow">INTERACTIVE CYBERSECURITY EXERCISE</span><h1 id="caseIntroTitle">Identify and report suspected unauthorized activity</h1><p class="case-subtitle">Use a simulated SIEM to investigate an international payment gateway, examine security evidence, and prepare an escalation brief.</p><div class="eyebrow case-company">YOUR CASE / HAMILTON INDUSTRIAL COMPONENTS</div><p>Hamilton Industrial Components (HIC) is a fictional Cincinnati-based manufacturer with operations in the United States, United Kingdom, and Germany. It pays international suppliers and business partners for materials, parts, and work through a Batch Transfer Gateway. In this case, you will examine a day that appears to have two sign-in periods when only one authorized processing session is expected. You will use a simulated security monitoring tool to investigate the unexpected activity, check for unusual large data transfers, and prepare an evidence-based report explaining your findings, uncertainties, and recommended next actions. You will be accompanied by <strong>Hannah, an independent Virtual CISO (Chief Information Security Officer) and experienced cybersecurity consultant</strong>, who will guide you through the tool and your investigation. She does not work for Hamilton.</p>`;$('main').prepend(introduction)}mountGuide(state.phase,{view:guideView,inspect})}
function bindExplorer(){for(const [id,k] of [['date','date'],['from','from'],['to','to'],['user','user'],['ip','ip'],['outcome','outcome'],['search','q']])$(id).addEventListener(id==='search'||id==='user'||id==='ip'?'input':'change',()=>{filter[k]=$(id).value;page=0;selectedBin=null;updateExplorer()});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{filter.category=b.dataset.category;page=0;selectedBin=null;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));updateExplorer()});$('daily').onclick=()=>{mode='daily';selectedBin=null;updateExplorer()};$('hourly').onclick=()=>{mode='hourly';if(filter.date==='all'){filter.date='2026-08-15';$('date').value=filter.date}selectedBin=null;updateExplorer()};$('clearFilters').onclick=()=>{filter={date:'all',category:'all',from:'00:00',to:'24:00',user:'',ip:'',outcome:'all',q:''};mode='daily';page=0;render()};if($('postWindow')){$('postWindow').onclick=()=>{filter.date='2026-08-15';filter.from='05:12';filter.to='17:21';filter.ip='';filter.user='';filter.outcome='all';filter.q='';mode='hourly';page=0;selectedBin=null;render()};$('approvedBank').onclick=()=>{filter.ip='203.0.113.80';$('ip').value=filter.ip;page=0;updateExplorer()};$('allDestinations').onclick=()=>{filter.ip='';$('ip').value='';page=0;updateExplorer()}}}
function updateExplorer(){const network=state.phase===5,all=visibleEvents(),flows=all.filter(e=>e.source==='edge-flow');$('daily').classList.toggle('active',mode==='daily');$('hourly').classList.toggle('active',mode==='hourly');const bins=mode==='daily'?(filter.date==='all'?days:[filter.date]):Array.from({length:24},(_,i)=>i);const data=bins.map(bin=>{const es=(network?flows:all).filter(e=>mode==='daily'?dayOf(e)===bin:hourOf(e)===bin);return {bin,count:es.length,out:es.reduce((a,e)=>a+e.bytes_out,0),in:es.reduce((a,e)=>a+e.bytes_in,0)}});const max=Math.max(1,...data.flatMap(b=>network?[b.out,b.in]:[b.count]));
let baseline='';if(network){const comparable=events.filter(e=>e.source==='edge-flow'&&dayOf(e)!=='2026-08-15'&&networkComparable(e));const perDay=days.filter(d=>d!=='2026-08-15').map(d=>comparable.filter(e=>dayOf(e)===d).reduce((a,e)=>a+e.bytes_out,0));baseline=`<div class="stats"><div class="stat"><strong>${formatBytes(flows.reduce((a,e)=>a+e.bytes_out,0))}</strong><small>Selected outbound</small></div><div class="stat"><strong>${formatBytes(flows.reduce((a,e)=>a+e.bytes_in,0))}</strong><small>Selected inbound</small></div><div class="stat"><strong>${formatBytes(perDay.reduce((a,v)=>a+v,0)/5)}</strong><small>Historical daily mean outbound, same hours & filters (Aug 10–14)</small></div></div>`;}
$('chartArea').innerHTML=baseline+(network?`<section class="traffic-explanation" id="morningTrafficExplanation"><h4>Why are there outbound bytes around 5 AM if sign-ins failed?</h4><p><strong>A rejected sign-in still involves two-way network traffic.</strong> A login request arrives at the gateway (purple, inbound); the gateway sends a response, such as a sign-in error or MFA challenge result (orange, outbound). A failed login does not mean zero bytes were sent.</p><p>In the default 5:12 AM–5:21 PM view, the orange 5 AM bar contains <strong>156,756 bytes (about 157 kB)</strong>: 156,340 bytes of small HTTPS authentication exchanges plus 416 bytes of routine DNS traffic. These are recorded exchanges, not a successful application session or a demonstrated payment-file extraction. The chart shows volume—not the contents of those responses.</p><div class="flow-diagram"><div class="flow-step">Sign-in requests arrive<br><strong>Purple · inbound</strong></div><span>→</span><div class="flow-step">Password / MFA checks fail<br><strong>No application session</strong></div><span>→</span><div class="flow-step">Gateway sends responses<br><strong>Orange · outbound</strong></div></div><div class="toolbar"><button data-chart-inspect="HIC-02366">Inspect a small exchange: HIC-02366</button><button id="blockedConnectionLink" data-chart-inspect="HIC-02725" class="primary">Open blocked connection HIC-02725</button></div><p class="caption">For HIC-02366, “success” describes the network exchange, not a successful login. The matching sign-in record HIC-02365 failed. HIC-02725 is a separate 5:33 AM connection attempt with outcome blocked and both byte counters at zero. It contributes no bytes to the orange peak.</p></section>`:'')+`<div class="timeline-navigation" role="status"><strong>${mode==='daily'?'Daily totals':'Hourly timeline'} · ${filter.date==='all'?'Mon, Aug 10–Sat, Aug 15, 2026':displayDay(filter.date)}</strong><span>${mode==='daily'?'The Date menu filters which day is shown. To look inside a day, click its bar or choose a date and then click Hourly detail.':'Each bar is one hour on the selected day. Click an hour to narrow the logs. Use Date to change the day, or Daily overview to return to daily totals.'}</span></div><div class="chart" role="group" aria-label="${network?'Network bytes':'Event counts'} by ${mode==='daily'?'date':'hour'}">${data.map(b=>{const label=mode==='daily'?displayDay(b.bin,true):clockLabel(`${b.bin}:00`,true);const button=(v,kind)=>`<button class="bar ${kind==='in'?'inbound':kind==='out'?'outbound':''} ${selectedBin===b.bin?'selected':''}" data-bin="${b.bin}" style="height:${Math.max(2,v/max*195)}px" title="${label}: ${network?formatBytes(v)+' '+kind:v+' events'}" aria-label="${mode==='daily'?displayDay(b.bin):label+' PT'}: ${network?Math.round(v)+' bytes '+kind:v+' events'}. Select this ${mode==='daily'?'date':'hour'}.">${!network&&v>0&&bins.length<10?`<span>${v}</span>`:''}</button>`;return `<div class="chart-col">${network?`<div class="chart-pair">${button(b.out,'out')}${button(b.in,'in')}</div>`:button(b.count,'events')}<span class="tick">${label}</span></div>`}).join('')}</div><div class="legend"><span><i class="swatch ${network?'out':''}"></i>${network?'Outbound bytes':'Event records'}</span>${network?'<span><i class="swatch in"></i>Inbound bytes</span>':''}<span>${mode==='daily'?'Click a day’s bar to open hourly detail':'Select an hour to filter the console'} · ${clockLabel(filter.from)}–${clockLabel(filter.to)} PT</span></div><p class="caption">${mode==='hourly'?'Hourly bins are clipped to your selected time range.':(filter.date==='all'?'Six complete Pacific calendar days.':'Daily total for '+displayDay(filter.date)+'.')} ${all.length} matching records${network?`; ${flows.length} byte-counted flows`:''}. Empty columns mean no matching records in supplied coverage.</p>`;
document.querySelectorAll('[data-bin]').forEach(b=>b.onclick=()=>{if(mode==='daily'){filter.date=b.dataset.bin;mode='hourly';$('date').value=filter.date;selectedBin=null}else{const h=+b.dataset.bin;filter.from=`${String(h).padStart(2,'0')}:00`;filter.to=`${String(h+1).padStart(2,'0')}:00`;$('from').value=filter.from;$('to').value=filter.to;selectedBin=h}page=0;updateExplorer()});document.querySelectorAll('[data-chart-inspect]').forEach(b=>b.onclick=()=>inspect(b.dataset.chartInspect));renderLogs(all);}
function networkComparable(e){const m=hourOf(e)*60+Number(e.timestamp.slice(14,16));return m>=minutes(filter.from)&&m<minutes(filter.to)&&(filter.category==='all'||e.category===filter.category)&&(!filter.user||String(e.user||'').includes(filter.user))&&(!filter.ip||e.src.includes(filter.ip)||e.dst.includes(filter.ip))&&(filter.outcome==='all'||e.outcome===filter.outcome)&&(!filter.q||JSON.stringify(e).toLowerCase().includes(filter.q.toLowerCase()))}
function formatBytes(n){return n>=1e6?`${(n/1e6).toFixed(2)} MB`:n>=1000?`${(n/1000).toFixed(1)} kB`:`${Math.round(n)} B`}
function renderLogs(list){const sorted=[...list].sort((a,b)=>{let x=a[sort.key]??'',y=b[sort.key]??'';return (typeof x==='number'?x-y:String(x).localeCompare(String(y)))*(sort.asc?1:-1)});page=Math.min(page,Math.max(0,Math.ceil(sorted.length/40)-1));const rows=sorted.slice(page*40,page*40+40);const cols=[['id','Event ID'],['timestamp','Timestamp (PT)'],['source','Source'],['src','Source IP'],['dst','Destination'],['user','Account'],['protocol','Protocol'],['type','Type'],['outcome','Outcome'],['password','Password'],['mfa','MFA'],['session','Session'],['bytes_out','Out B'],['bytes_in','In B']];$('logCount').textContent=`${list.length} records`;$('logs').innerHTML=`<div class="table-wrap"><table><thead><tr>${cols.map(([k,t])=>`<th scope="col" aria-sort="${sort.key===k?(sort.asc?'ascending':'descending'):'none'}"><button data-sort="${k}">${t} ${sort.key===k?(sort.asc?'↑':'↓'):''}</button></th>`).join('')}</tr></thead><tbody>${rows.map(e=>`<tr>${cols.map(([k])=>`<td>${k==='id'?`<button class="link-button" data-event="${e.id}">${e.id}${state.pins.includes(e.id)?' ★':''}</button>`:k==='timestamp'?stamp(e):k==='outcome'?`<span class="${e.outcome}">${e.outcome}</span>`:esc(e[k])}</td>`).join('')}</tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No records match. Adjust the filters or clear them.</div>'}</div><div class="log-footer"><span>Showing ${rows.length?page*40+1:0}–${Math.min((page+1)*40,list.length)} of ${list.length} · inspect event IDs for descriptions and UTC</span><div><button id="pageBack" aria-label="Previous page of events" ${page===0?'disabled':''}>←</button> <button id="pageNext" aria-label="Next page of events" ${(page+1)*40>=list.length?'disabled':''}>→</button></div></div>`;document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{sort={key:b.dataset.sort,asc:sort.key===b.dataset.sort?!sort.asc:true};renderLogs(list)});document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>inspect(b.dataset.event));$('pageBack').onclick=()=>{page--;renderLogs(list)};$('pageNext').onclick=()=>{page++;renderLogs(list)}}
function inspect(id){const e=events.find(e=>e.id===id);$('detailBody').innerHTML=`<span class="badge">${e.id}</span><h3 style="margin-top:15px">${esc(e.type)}</h3><p>${esc(e.description)}</p><dl class="facts"><dt>Pacific time</dt><dd>${stamp(e)}</dd><dt>UTC record</dt><dd>${e.timestamp}</dd><dt>Source → destination</dt><dd>${e.src} → ${e.dst}</dd><dt>Account / session</dt><dd>${esc(e.user)} / ${esc(e.session)}</dd><dt>Overall outcome</dt><dd>${esc(e.outcome)}</dd><dt>Password / MFA</dt><dd>${e.password} / ${e.mfa}</dd><dt>Bytes out / in</dt><dd>${e.bytes_out} / ${e.bytes_in} B (flow records only)</dd></dl>${e.enrichment?`<div class="callout">${esc(e.enrichment)}</div>`:''}<div class="toolbar"><button id="pinEvent" class="primary">${state.pins.includes(id)?'Remove from':'Pin to'} evidence brief</button></div><p class="caption">Pinning adds this event to the Selected evidence section in phase 7. It stays saved in this browser and accompanies your report and JSON/CSV exports. You still need to explain why it supports your finding.</p><details><summary>Full underlying record & field values</summary><pre class="raw">${esc(JSON.stringify(e,null,2))}</pre></details>`;$('pinEvent').onclick=()=>{state.pins=state.pins.includes(id)?state.pins.filter(x=>x!==id):[...state.pins,id];persist();document.querySelectorAll('[data-recommend-pin]').forEach(b=>b.textContent=state.pins.includes(b.dataset.recommendPin)?'Pinned ✓':'Pin record');inspect(id);if($('logs'))renderLogs(visibleEvents())};if(!$('detail').open)$('detail').showModal()}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportData(){return {exercise:'The Second Peak',ticket:'SEC-2026-0816',exported_at:new Date().toISOString(),display_timezone:TZ,coverage:{start:ledger.coverage_start,end:ledger.coverage_end},brief:Object.fromEntries(questions.map((q,i)=>[q,state.notes[i]])),evidence:events.filter(e=>state.pins.includes(e.id))}}
function csvCell(v){let s=typeof v==='object'&&v!==null?JSON.stringify(v):String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function bindBrief(){document.querySelectorAll('[data-debrief-inspect]').forEach(b=>b.onclick=()=>inspect(b.dataset.debriefInspect));document.querySelectorAll('[data-note]').forEach(t=>t.oninput=()=>{state.notes[+t.dataset.note]=t.value;persist();$('printed'+t.dataset.note).textContent=t.value||'Not completed.'});document.querySelectorAll('[data-unpin]').forEach(b=>b.onclick=()=>{state.pins=state.pins.filter(id=>id!==b.dataset.unpin);persist();render()});$('printBrief').onclick=()=>window.print();$('exportJson').onclick=()=>download('second-peak-brief.json',JSON.stringify(exportData(),null,2),'application/json');$('exportCsv').onclick=()=>{const data=exportData(),fields=Object.keys(events[0]),head=['record_type','section','observation',...fields],rows=questions.map((q,i)=>['brief',q,state.notes[i],...fields.map(()=>null)]).concat(data.evidence.map(e=>['evidence','','',...fields.map(k=>e[k])]));download('second-peak-brief.csv',[head,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')};$('reviewBrief').onclick=()=>{const text=state.notes.join(' '),missing=questions.filter((_,i)=>!state.notes[i].trim()),messages=[];if(missing.length)messages.push(`Incomplete sections: ${missing.join('; ')}.`);if(!state.pins.length)messages.push('No records pinned. Select evidence to make your assessment traceable.');const citations=text.match(/HIC-\d{5}/g)||[];if(!citations.some(id=>events.some(e=>e.id===id)))messages.push('Add recognizable event IDs and timestamps to support observations.');if(citations.some(id=>!events.some(e=>e.id===id)))messages.push('Some cited event IDs do not exist in this ledger; verify them.');if(/stole|breached|guarantee|no data was stolen|no exfiltration occurred|physically|proves.*location/i.test(text))messages.push('Review categorical claims about theft, breach, MFA guarantees, absence of extraction, or physical location. A keyword match is a prompt to review context, not a verdict. Qualify the claim and cite evidence.');messages.push('Self-review: separate password verification from session creation; state traffic coverage limits; distinguish no observed unusual large transfer from proof of no extraction; name the next responsible parties.','This checklist does not verify the truth of your conclusions.');$('feedback').textContent=messages.join('\n\n')}}
if($('exerciseHome'))$('exerciseHome').onclick=()=>{setPhase(0);window.scrollTo({top:0,behavior:'instant'})};
$('closeDetail').onclick=()=>$('detail').close();$('glossaryButton').onclick=()=>$('glossary').showModal();$('closeGlossary').onclick=()=>$('glossary').close();$('reset').onclick=()=>{if(confirm('Remove this exercise’s saved notes and pinned evidence from this browser?')){state.phase=0;state.pins=[];state.notes=Array(9).fill('');persist();render()}};
async function loadEvidence(){try{const response=await fetch('events.json',{cache:'no-cache'});if(!response.ok)throw Error(`HTTP ${response.status}`);ledger=await response.json();events=ledger.events;days=[...new Set(events.map(dayOf))];$('recordCount').textContent=`${events.length.toLocaleString()} synthetic records.`;render();window.dispatchEvent(new Event('exercise-ready'))}catch(e){$('main').innerHTML=`<h2>Evidence could not be loaded</h2><p>Serve this folder over HTTP, then reload. The event ledger must be beside this page as events.json.</p><p>${esc(e.message)}</p>`;window.dispatchEvent(new Event('exercise-ready'))}}
loadEvidence();

function guideView({date='all',mode:nextMode='daily',hour=null}){if(!document.getElementById('chartArea'))return;filter={date,category:'all',from:hour===null?'00:00':`${String(hour).padStart(2,'0')}:00`,to:hour===null?'24:00':`${String(hour+1).padStart(2,'0')}:00`,user:'',ip:'',outcome:'all',q:''};mode=nextMode;page=0;selectedBin=hour;for(const [id,key] of [['date','date'],['from','from'],['to','to'],['user','user'],['ip','ip'],['outcome','outcome'],['search','q']])$(id).value=filter[key];document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category==='all'));updateExplorer()}
